using System;using System.Threading;using Compose.Net;using DesignSystem;using SharpExtensions;using UnityEngine.UIElements;using SystemColor = System.Drawing.Color;// ReSharper disable ArrangeNamespaceBodynamespace UnityCompose.Samples.Behaviors.Content{    internal partial class ButtonSample : ComposeUI    {        [SerializeField] private Texture2D texture = null!;        [SerializeField] private Material material = null!;        [Composable]        protected override void Content()        {            Layout();        }        [Composable]        protected override void Preview()        {            Layout();        }        [Composable]        private void Layout()        {            Column(                verticalArrangement: Arrangement.Center,                horizontalAlignment: Alignment.CenterHorizontally,                modifier: Modifier                    .FillMaxSize(),                content: Button            );        }        [Composable]        private static void Button()        {            var interactionSource = Remember(MutableInteractionSource);            var hovered = interactionSource.CollectIsHoveredAsState().Value;            var shadowProgress = AnimateFloatAsState(hovered.ToInt()).Value;            var pressed = interactionSource.CollectIsPressedAsState().Value;            Box(                contentAlignment: Alignment.Center,                modifier: Modifier                    .Height(200.Dp())                    .Width(600.Dp())                    .Background(                        Brush.LinearGradient(                            ImmutableStableListOf(                                Color.lightGreen.ToSystemColor(),                                Color.dodgerBlue.ToSystemColor()                            )                        ),                        RoundedCornerShape(16.Dp())                    )                    .Padding(16.Dp())                    .Clip(RoundedCornerShape(AnimateFloatAsState(hovered ? 48 : 16).Value.Dp()))                    .DropShadow(                        shape: RoundedCornerShape(16.Dp()),                        shadow: Shadow(                            spread: 20.Dp(),                            color: Color.LerpUnclamped(new Color(), Color.black, shadowProgress)                                .ToSystemColor(),                            radius: 32.Dp() * shadowProgress                        )                    )                    .InnerShadow(                        shape: RoundedCornerShape(16.Dp()),                        shadow: Shadow(                            spread: 8.Dp(),                            color: Color.LerpUnclamped(new Color(), Color.white.With(a: 0.5f), 1)                                .ToSystemColor(),                            radius: 12.Dp()                        )                    )                    .Clickable(                        onClick: () => Debug.Log("Click"),                        interactionSource: interactionSource,                        indication: null                    ),                content: () =>                {                    Text(                        text: pressed ? "Clicked" : "Click me",                        color: Color.white.ToSystemColor(),                        fontSize: 80.Sp()                    );                }            );        }    }}